from pathlib import Path
import subprocess,time,json,base64,hashlib
BUILD=''
SHA='70659fd8cc14e7282956c610183cc44782b5e96f618e1537cc694c99292c6028'
r=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review');p=r/'reports/stage5_04_board/screen_then_build';p.mkdir()
start=time.monotonic();baseline=r/'reports/stage5_04_board/raw_tts_baseline_2t/result.json'
while not baseline.exists():
 assert time.monotonic()-start<1100,'baseline wait exceeded'
 time.sleep(1)
result=json.loads(baseline.read_text());assert result['returncode']==0 and not result['termination_reason'],result
print('BASELINE_COMPLETED_BEFORE_SCREEN',json.dumps(result),flush=True)
for threads in [1,4,6]:
 name='raw_tts_screen_'+str(threads)+'t'
 cmd=['python3',str(r/'tools/stage5_04_run.py'),'--name',name,'--exe',str(r/'reports/stage5_04_board/raw_baseline_build/tts_bench'),'--timeout','600','--','{KOKORO}','{REPORT}',str(threads),'3']
 code=subprocess.run(cmd,timeout=650).returncode
 if code:raise SystemExit(code)
(p/'baseline_build.py').write_bytes(base64.b64decode(BUILD));assert hashlib.sha256((p/'baseline_build.py').read_bytes()).hexdigest()==SHA
raise SystemExit(subprocess.run(['python3',str(p/'baseline_build.py')],timeout=950).returncode)
